import sys
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])
    E_max = int(input_data[2])

    R = []
    idx = 3
    for _ in range(N):
        R.append(int(input_data[idx]))
        idx += 1

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = int(input_data[idx])
        v = int(input_data[idx+1])
        c = int(input_data[idx+2])
        dt = int(input_data[idx+3])
        W = int(input_data[idx+4])
        idx += 5
        windows = []
        for _ in range(W):
            start = int(input_data[idx])
            end = int(input_data[idx+1])
            windows.append((start, end))
            idx += 2
        adj[u].append((v, c, dt, windows))


    pq = [(0, 0, E_max)]


    best = [[float('inf')] * (E_max + 1) for _ in range(N)]
    best[0][E_max] = 0

    while pq:
        t, u, e = heapq.heappop(pq)


        if t > best[u][e]:
            continue


        if u == N - 1:
            print(t)
            return


        if e < E_max and R[u] != -1:
            nt = t + R[u]
            ne = e + 1
            if nt < best[u][ne]:
                best[u][ne] = nt
                heapq.heappush(pq, (nt, u, ne))


        for v, c, dt, windows in adj[u]:
            if e >= c:

                best_arr = float('inf')
                for ws, we in windows:
                    t_dep = max(t, ws)
                    if t_dep + dt <= we:
                        best_arr = min(best_arr, t_dep + dt)


                if best_arr != float('inf'):
                    ne = e - c
                    if best_arr < best[v][ne]:
                        best[v][ne] = best_arr
                        heapq.heappush(pq, (best_arr, v, ne))

    print("UNREACHABLE")

if __name__ == '__main__':
    solve()
